do
  HissatsuReforged = type(HissatsuReforged) == "table" and HissatsuReforged or {}
  HissatsuReforged.rank_items = type(HissatsuReforged.rank_items) == "table" and HissatsuReforged.rank_items or {}
  local RankItems = HissatsuReforged.rank_items
  RankItems.ITEMS = 840614655 --[[CMND_HISSATSUREFORGED_RANK_ITEMS]]  -- () -> raise id, last id, use cap, last grade
  RankItems.ITEM = 3452202073 --[[CMND_HISSATSUREFORGED_RANK_ITEM]]
  RankItems.ITEM_NUM = 2011560392                        -- CMND_GET_ITEM_NUM (item, false) -> stock
  RankItems.DEL_ITEM = 425598937                         -- CMND_DELETE_ITEM (item, count)
  RankItems.ITEM_NAME = 1883585771                       -- (item, 0) -> the item's name (retail UpdateItemEquipLine)
  RankItems.SKILL_INFO = 2580586398                      -- CMND_GET_SOCCER_SKILL_INFO (skill, 16 = growth type)
  RankItems.TEXT_GET = 4074371074                        -- CMND_TEXT_GET (text id) -> string
  RankItems.TX = {
    GUIDE = 2750115802 --[[HissatsuReforged.RankItemGuide]], LEVEL = 4087309564 --[[HissatsuReforged.RankItemLevel]],
    CONFIRM = 2386038472 --[[HissatsuReforged.RankItemConfirm]], CONFIRM_FIRST = 3849458839 --[[HissatsuReforged.RankItemConfirmFirst]], DONE = 1665659192 --[[HissatsuReforged.RankItemDone]],
    NONE = 217715036 --[[HissatsuReforged.RankItemNone]], NEEDS_LAST = 3938878509 --[[HissatsuReforged.RankItemNeedsLast]],
    MAX = 728838670 --[[HissatsuReforged.RankItemMax]], NO_GRADE = 3759509224 --[[HissatsuReforged.RankItemNoGrade]],
    FAILED = 2924947766 --[[HissatsuReforged.RankItemFailed]], PRESS_AGAIN = 1404536303 --[[HissatsuReforged.RankItemPressAgain]],
    KEY = 635903717 --[[HissatsuReforged.RankItemUseKey]],
  }
  -- Refusal of each code of CMND_HISSATSUREFORGED_RANK_ITEM.
  RankItems.REFUSALS = {
    [1] = {reason = "not_a_rank_item", text = "FAILED"},
    [2] = {reason = "no_grade", text = "NO_GRADE"},
    [3] = {reason = "already_max", text = "MAX"},
    [4] = {reason = "needs_second_to_last", text = "FAILED"},
    [5] = {reason = "not_in_set", text = "NO_GRADE"},
    [-1] = {reason = "bad_args", text = "FAILED"},
    [-2] = {reason = "hissatsu_level_up_off", text = "FAILED"},
  }

  RankItems.logger = VRFW.logger.new("HissatsuReforged rank_items")

  -- One line, joined here: the log command keeps 8 arguments.
  function RankItems.log(view, ...)
    local parts = {view}
    for k = 1, select("#", ...) do
      parts[#parts + 1] = tostring((select(k, ...)))
    end
    RankItems.logger(table.concat(parts, " "))
  end

  function RankItems.text(id)
    local ok, s = pcall(funcLuaCommand, RankItems.TEXT_GET, id)
    return (ok and type(s) == "string") and s or ""
  end

  function RankItems.fill(s, values)
    return (string.gsub(s, "{(%w+)}", function(k)
      local v = values[k]
      if v == nil then
        return nil
      end
      return tostring(v)
    end))
  end

  -- raise item id, last-grade item id (0, 0 = Hissatsu Reforged's script does not answer)
  function RankItems.ids()
    local ok, raise, last = pcall(funcLuaCommand, RankItems.ITEMS)
    if not ok or type(raise) ~= "number" or type(last) ~= "number" then
      return 0, 0
    end
    return VRFW.ids.unsigned(raise), VRFW.ids.unsigned(last)
  end

  function RankItems.active()
    local raise, last = RankItems.ids()
    return raise ~= 0 or last ~= 0
  end

  function RankItems.num(id)
    if id == 0 then
      return 0
    end
    local ok, v = pcall(funcLuaCommand, RankItems.ITEM_NUM, id, false)
    return ok and (tonumber(v) or 0) or 0
  end

  -- how many rank items the player holds (both kinds)
  function RankItems.owned()
    local raise, last = RankItems.ids()
    return RankItems.num(raise) + RankItems.num(last)
  end

  function RankItems.item_name(id)
    local ok, s = pcall(funcLuaCommand, RankItems.ITEM_NAME, id, 0)
    if ok and type(s) == "string" and s ~= "" then
      return s
    end
    return string.format("%08X", VRFW.ids.unsigned(id))
  end

  function RankItems.label(skill, grade)
    if grade > 0 and type(AppendEvoCodeToSkillName) == "function" then
      local okq, okv, growth = pcall(funcLuaCommand, RankItems.SKILL_INFO, skill, 16)
      if okq and okv and type(growth) == "number" then
        local ok, s = pcall(AppendEvoCodeToSkillName, "", grade, growth)
        if ok and type(s) == "string" and s ~= "" then
          return s
        end
      end
    end
    return RankItems.fill(RankItems.text(RankItems.TX.LEVEL), {n = grade + 1})
  end

  function RankItems.check(chara, skill, item, apply)
    if item == 0 then
      return nil
    end
    local ok, code, old, new = pcall(funcLuaCommand, RankItems.ITEM, chara, skill, item, apply == true)
    if not ok or type(code) ~= "number" then
      return nil
    end
    return code, tonumber(old) or 0, tonumber(new) or 0
  end

  function RankItems.plan(chara, skill, move_name)
    local raise, last = RankItems.ids()
    local code, old, new = RankItems.check(chara, skill, raise, false)
    local item = raise
    if code == 3 then                                    -- raise item capped: second-to-last or last grade
      local code2, old2, new2 = RankItems.check(chara, skill, last, false)
      if code2 ~= nil then
        code, old, new, item = code2, old2, new2, last
      end
    end
    local plan = {chara = chara, skill = skill, item = item, code = code, old = old or 0, new = new or 0, last = last}
    plan.values = {move = move_name or "", old = RankItems.label(skill, plan.old), new = RankItems.label(skill, plan.new)}
    if code == nil then
      plan.refusal = {reason = "no_answer", text = "FAILED"}
    elseif code ~= 0 then
      plan.refusal = RankItems.REFUSALS[code] or {reason = "code_" .. tostring(code), text = "FAILED"}
    else
      plan.values.item = RankItems.item_name(item)
      plan.values.count = RankItems.num(item)
      if plan.values.count < 1 then
        plan.refusal = item == last and {reason = "no_manual", text = "NEEDS_LAST"} or {reason = "no_book", text = "NONE"}
      end
    end
    return plan
  end

  function RankItems.refusal_text(plan)
    return RankItems.fill(RankItems.text(RankItems.TX[plan.refusal.text] or RankItems.TX.FAILED), plan.values)
  end

  function RankItems.confirm_text(plan)
    return RankItems.fill(RankItems.text(plan.old == 0 and RankItems.TX.CONFIRM_FIRST or RankItems.TX.CONFIRM), plan.values)
  end

  -- Logs one line per refusal.
  function RankItems.log_refused(view, plan)
    RankItems.log(view, "refused", plan.refusal.reason, "chara", tostring(plan.chara), "move", VRFW.ids.hex_text(plan.skill),
      "item", VRFW.ids.hex_text(plan.item), "code", tostring(plan.code), "grade", tostring(plan.old), "->", tostring(plan.new))
  end

  -- Uses the planned item.
  function RankItems.use(view, plan)
    local code, old, new = RankItems.check(plan.chara, plan.skill, plan.item, true)
    if code ~= 0 then
      plan.code = code
      plan.refusal = RankItems.REFUSALS[code or 0] or {reason = "apply_failed", text = "FAILED"}
      RankItems.log_refused(view, plan)
      return false, RankItems.text(RankItems.TX.FAILED)
    end
    local before = RankItems.num(plan.item)
    funcLuaCommand(RankItems.DEL_ITEM, plan.item, 1)
    RankItems.log(view, "used", VRFW.ids.hex_text(plan.item), "on", VRFW.ids.hex_text(plan.skill), "chara", tostring(plan.chara),
      "grade", tostring(old), "->", tostring(new), "stock", tostring(before), "->", tostring(RankItems.num(plan.item)))
    plan.values.old, plan.values.new = RankItems.label(plan.skill, old or 0), RankItems.label(plan.skill, new or 0)
    return true, RankItems.fill(RankItems.text(RankItems.TX.DONE), plan.values)
  end

  RankItems.board = {
    RING = 2907318182,               -- team13_09_effect_grid_focus_ring (the node focus)
    FOCUS_IDX = 2603265800,          -- (layer) -> focused instance
    PIECE_INFO = 4147077179,
    MOVE_PIECE = {[0] = true, [1] = true},   -- piece categories holding a move (0 move, 1 aura / special move)
    CTRL = 1332654303,               -- MENU_CTRL
    CTRL_ANALOG = 2748927068,        -- MENU_CTRL_WITH_ANALOG_MOVE_FOCUS
    CHECK_INPUT = 4265778440,        -- CMND_CHECK_INPUT_CMD (ctrl, command) -> pressed
    KEY = 637335895 --[[CMD_FUNC1]],              -- Start (keyboard: the game's Start key)
    RETAIL_START_GLYPH = 3875068402,
    TELOP = 157759052,               -- team13_18_unlimited_skill_telop
    TELOP_TEXT = 3359986143,
    SET_TEXT = 1083631230,           -- CMND_SET_MENU_TEXT_STRING (layer, node, text)
    TEXT_PLATE = 1172899594,         -- (layer, idx, node): the plate follows the text
    LAYER_VISIBLE = 711242136,
    SOUND = 1917805374, SE_OK = 3848881948, SE_DECIDE = 4235359837, SE_NG = 2086672038,
    PARAM_CHARA = 4161869490,
    SKILL_INFO = 2580586398,         -- (skill, 4) -> ok, name text id
    NAME_TEXT = 720417636,           -- (name text id) -> string
    TELOP_FRAMES = 300,              -- how long a question / an answer stays (frames)
    KEY_COOLDOWN = 12,               -- frames between two presses
    chara = nil, mode = nil, last_idx = nil, guide_on = false, armed = nil, telop_ours = false, telop_frames = 0,
    cooldown = 0, detail = nil,
  }
  local Board = RankItems.board

  function Board.sound(id)
    pcall(funcLuaCommand, Board.SOUND, id)
  end

  function Board.move_name(skill)
    local ok, found, name_id = pcall(funcLuaCommand, Board.SKILL_INFO, skill, 4)
    if ok and found and type(name_id) == "number" then
      local okn, name = pcall(funcLuaCommand, Board.NAME_TEXT, name_id)
      if okn and type(name) == "string" and name ~= "" then
        return name
      end
    end
    return string.format("%08X", VRFW.ids.unsigned(skill))
  end

  -- Returns the focused piece.
  function Board.focused()
    local okf, idx = pcall(funcLuaMenuCommand, Board.FOCUS_IDX, Board.RING)
    if not okf or type(idx) ~= "number" or idx < 0 then
      return nil
    end
    local r = {pcall(funcLuaMenuCommand, Board.PIECE_INFO, idx)}
    if not r[1] then
      return nil
    end
    local skill, selected, category, overwrite, secret = r[4], r[5], r[6], r[12], r[13]
    local move = 0
    if type(selected) == "number" and selected ~= 0 then
      move = selected
    elseif type(overwrite) == "number" and overwrite ~= 0 then
      move = overwrite
    elseif type(skill) == "number" then
      move = skill
    end
    return {idx = idx, skill = VRFW.ids.unsigned(move), category = category, secret = secret == true}
  end

  function Board.is_move_piece(piece)
    return piece ~= nil and Board.MOVE_PIECE[piece.category] == true and not piece.secret and piece.skill ~= 0
  end

  function Board.busy()
    local better_qol = rawget(_ENV, "BetterQoL")
    local partners = type(better_qol) == "table" and better_qol.combo_partners or nil
    if type(partners) == "table" and partners.co ~= nil then
      return true
    end
    if type(IsRunningManageCoroutine) == "function" then
      for i = 1, 13 do
        local ok, running = pcall(IsRunningManageCoroutine, i)
        if ok and running == true then
          return true
        end
      end
    end
    return false
  end

  function Board.pressed()
    local ok, hit = pcall(funcLuaCommand, Board.CHECK_INPUT, Board.CTRL, Board.KEY)
    if ok and hit == true then
      return true
    end
    local ok2, hit2 = pcall(funcLuaCommand, Board.CHECK_INPUT, Board.CTRL_ANALOG, Board.KEY)
    return ok2 and hit2 == true
  end

  function Board.say(text)
    funcLuaMenuCommand(Board.SET_TEXT, Board.TELOP, Board.TELOP_TEXT, text)
    funcLuaMenuCommand(Board.TEXT_PLATE, Board.TELOP, 0, Board.TELOP_TEXT)
    funcLuaMenuCommand(Board.LAYER_VISIBLE, Board.TELOP, 0, true)
    Board.telop_ours, Board.telop_frames = true, Board.TELOP_FRAMES
  end

  function Board.quiet()
    Board.armed = nil
    if Board.telop_ours then
      Board.telop_ours = false
      pcall(funcLuaMenuCommand, Board.LAYER_VISIBLE, Board.TELOP, 0, false)
    end
  end

  function Board.guide_wanted()
    if (Board.mode ~= 0 and Board.mode ~= 1) or Board.chara == nil or not Board.is_move_piece(Board.focused()) then
      return false
    end
    return RankItems.active()
  end

  -- Start is ours on a move piece (the retail quick bean equip is withheld there)
  function Board.start_is_ours()
    return Board.chara ~= nil and Board.is_move_piece(Board.focused()) and RankItems.active()
  end

  function Board.press()
    local piece = Board.focused()
    if Board.chara == nil or not Board.is_move_piece(piece) then
      Board.sound(Board.SE_NG)
      RankItems.log("board", "refused", "no_move_piece", "chara", tostring(Board.chara))
      return
    end
    local armed = Board.armed
    if armed ~= nil and armed.idx == piece.idx and armed.skill == piece.skill and armed.chara == Board.chara then
      Board.armed = nil
      local used, text = RankItems.use("board", armed.plan)
      Board.sound(used and Board.SE_DECIDE or Board.SE_NG)
      Board.say(text)
      if used then
        if Board.detail ~= nil and type(UpdateDetailWindow) == "function" then
          pcall(UpdateDetailWindow, table.unpack(Board.detail, 1, Board.detail.n))
        end
        if type(UpdateFooterButtonGuide) == "function" then
          pcall(UpdateFooterButtonGuide, Board.mode)
        end
      end
      return
    end
    local plan = RankItems.plan(Board.chara, piece.skill, Board.move_name(piece.skill))
    if plan.refusal ~= nil then
      Board.armed = nil
      RankItems.log_refused("board", plan)
      Board.sound(Board.SE_NG)
      Board.say(RankItems.refusal_text(plan))
      return
    end
    Board.sound(Board.SE_OK)
    Board.say(RankItems.confirm_text(plan) .. "\n" .. RankItems.text(RankItems.TX.PRESS_AGAIN))
    Board.armed = {idx = piece.idx, skill = piece.skill, chara = Board.chara, plan = plan}
    RankItems.log("board", "asked", VRFW.ids.hex_text(plan.item), "on", VRFW.ids.hex_text(plan.skill), "chara",
      tostring(Board.chara), "grade", tostring(plan.old), "->", tostring(plan.new))
  end

  -- every frame (after the screen's Step)
  function Board.poll()
    if Board.cooldown > 0 then
      Board.cooldown = Board.cooldown - 1
    end
    if Board.telop_ours and Board.telop_frames > 0 then
      Board.telop_frames = Board.telop_frames - 1
      if Board.telop_frames == 0 then
        Board.quiet()
      end
    end
    if (Board.mode ~= 0 and Board.mode ~= 1) or Board.busy() then
      return
    end
    local okf, idx = pcall(funcLuaMenuCommand, Board.FOCUS_IDX, Board.RING)
    if okf and idx ~= Board.last_idx then
      Board.last_idx = idx
      Board.quiet()
      local want = Board.guide_wanted()
      if want ~= Board.guide_on and type(UpdateFooterButtonGuide) == "function" then
        pcall(UpdateFooterButtonGuide, Board.mode)
      end
    end
    if Board.cooldown == 0 and Board.pressed() and Board.start_is_ours() then
      Board.cooldown = Board.KEY_COOLDOWN
      Board.press()
    end
  end

  function Board.set_chara(chara)
    if type(chara) == "number" and chara ~= 0 then
      if chara ~= Board.chara then
        Board.quiet()
      end
      Board.chara = chara
    end
  end

  VRFW.host.wrap("OnInit", function(previous)
    return function(...)
      Board.chara, Board.mode, Board.last_idx, Board.guide_on, Board.detail = nil, nil, nil, false, nil
      Board.armed, Board.telop_ours, Board.telop_frames, Board.cooldown = nil, false, 0, 0
      pcall(function()
        if VRFW.param.has(Board.PARAM_CHARA) then
          Board.set_chara(VRFW.param.get(Board.PARAM_CHARA))
        end
      end)
      return previous(...)
    end
  end)

  VRFW.host.wrap("OnChangeTargetChara", function(previous)
    return function(chara, ...)
      Board.set_chara(chara)
      Board.last_idx = nil
      return previous(chara, ...)
    end
  end)

  -- (charaStHdl, showTeamDockNo, teamDockType, formationId, selectCharaIdx, ...)
  VRFW.host.wrap("UpdateAbilityLearningBoardCharaCard", function(previous)
    return function(chara, ...)
      Board.set_chara(chara)
      return previous(chara, ...)
    end
  end)

  if VRFW.footer_prompts ~= nil then
    VRFW.footer_prompts.add({
      name = "HissatsuReforged.RankItemUse",
      menu = "ability_learning_board_menu",
      text = RankItems.TX.GUIDE,
      icon = RankItems.TX.KEY,
      command = Board.KEY,
      replaces = Board.RETAIL_START_GLYPH,
      order = 100,
      when = function()
        return Board.guide_on
      end,
    })
    VRFW.footer_prompts.attach("ability_learning_board_menu", "UpdateFooterButtonGuide")
  end

  VRFW.host.wrap("UpdateFooterButtonGuide", function(previous)
    return function(mode, ...)
      Board.mode = mode or 0
      local ok, want = pcall(Board.guide_wanted)
      Board.guide_on = ok and want == true
      return previous(mode, ...)
    end
  end)

  -- Start on a move piece
  VRFW.host.wrap("OpenBeansSetMenu", function(previous)
    return function(...)
      local ok, ours = pcall(Board.start_is_ours)
      if ok and ours then
        RankItems.log("board", "quick bean equip withheld (Start on a move piece)")
        return
      end
      return previous(...)
    end
  end)

  VRFW.host.wrap("ResetFooterButtonGuide", function(previous)
    return function(...)
      Board.mode, Board.guide_on = nil, false
      Board.quiet()
      return previous(...)
    end
  end)

  -- Wraps the detail card's last call.
  VRFW.host.wrap("UpdateDetailWindow", function(previous)
    return function(...)
      Board.detail = table.pack(...)
      return previous(...)
    end
  end)

  -- The retail telop took the plate back (an unlimited move's piece).
  VRFW.host.wrap("UpdateUnlimitedSkillTelop", function(previous)
    return function(...)
      Board.telop_ours, Board.armed = false, nil
      return previous(...)
    end
  end)

  VRFW.host.wrap("Step", function(previous)
    return function(...)
      local r = table.pack(previous(...))
      local ok, err = pcall(Board.poll)
      if not ok then
        RankItems.log("board", "poll failed", tostring(err))
      end
      return table.unpack(r, 1, r.n)
    end
  end)
end
